def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if n == 0:
        return []

    # Coordinate-compress values to 1..m for a Fenwick tree
    vals = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)

    def add(pos: int, delta: int) -> None:
        while pos <= m:
            tree[pos] += delta
            pos += pos & -pos

    def prefix(pos: int) -> int:
        total = 0
        while pos > 0:
            total += tree[pos]
            pos -= pos & -pos
        return total

    res = [0] * n
    for i in range(n):
        # Window for i is indices [i-k, i-1]; slide it by adding i-1 and dropping i-k-1
        if i >= 1:
            add(rank[a[i - 1]], 1)
        if i - k - 1 >= 0:
            add(rank[a[i - k - 1]], -1)

        window_size = min(i, k)
        # Elements in window that are <= a[i] are subtracted from the window size
        res[i] = window_size - prefix(rank[a[i]])

    return res
